"""Validate the real JavaScript camera PDF writer without a browser or camera device."""
import base64
from io import BytesIO
import json
from pathlib import Path
import shutil
import subprocess
import pytest
from pypdf import PdfReader

PHOTOS = [{'width': 12, 'height': 20, 'base64': ''}, {'width': 20, 'height': 12, 'base64': ''}, {'width': 16, 'height': 16, 'base64': ''}]

@pytest.mark.skipif(not shutil.which('node'), reason='Node.js is required for the camera PDF writer')
def test_camera_pdf_retains_order_dimensions_and_exact_jpeg_bytes():
    module = Path(__file__).resolve().parents[2] / 'source/local-test/camera-pdf.mjs'
    script = """
import {photoPdf} from MODULE;
const photos = PHOTOS.map(p=>({...p,bytes:new Uint8Array(Buffer.from(p.base64,'base64'))}));
const reversed = [photos[2], photos[0], photos[1]];
console.log(Buffer.from(await photoPdf(reversed).arrayBuffer()).toString('base64'));
for (const invalid of [[], Array(21).fill(photos[0]), [{...photos[0],width:0}]]) {
  let failed=false;try {photoPdf(invalid);} catch {failed=true;}
  if (!failed) process.exit(2);
}
""".replace('MODULE', json.dumps(module.as_uri())).replace('PHOTOS', json.dumps(PHOTOS))
    result = subprocess.run(['node','--input-type=module','-e',script],capture_output=True,text=True,timeout=30)
    assert result.returncode==0, result.stderr
    document=PdfReader(BytesIO(base64.b64decode(result.stdout)),strict=True)
    assert len(document.pages)==3
    for page, original in zip(document.pages,[PHOTOS[2],PHOTOS[0],PHOTOS[1]]):
        image=page['/Resources']['/XObject']['/Photo']
        assert (image['/Width'],image['/Height'])==(original['width'],original['height'])
        assert image.get_data()==base64.b64decode(original['base64'])
        assert page.get_contents().get_data().endswith(b'/Photo Do Q')
